import React, {useEffect, useRef, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUpLeft,ArrowDownLeft,ArrowLeft,ArrowRight,Plus,Search,Bell,LayoutDashboard,Spade,ChartNoAxesCombined,Wallet,Users,Settings,ChevronLeft,LogOut,Check,X,Clock,Download,Copy,ShieldCheck,TrendingUp,Trophy,CalendarDays,MoreHorizontal,Play,CheckCheck,Info,FileClock,RefreshCw,Menu,UserRound,Upload,MapPin,KeyRound} from 'lucide-react';
import '@fontsource-variable/heebo';
import './styles.css';
import MonthlySummary from './MonthlySummary';
import Elapsed from './Elapsed';
import {uid,money,date,month,israelDay,cents,emptyState,buyTotal,calculate,settle,validateTransfers,balance,debts,statistics,command,replay,place,sessionTitle,canHost,normalizePhone,DEFAULT_PASSWORD} from './domain';
import {load,save,mutate,startDemo,download,DEMO,hasPassword,checkPassword,setPassword,resetPassword} from './store';

const nav=[['home','מבט על השולחן',LayoutDashboard],['sessions','הישיבות שלי',Spade],['stats','סטטיסטיקות',ChartNoAxesCombined],['debts','חובות והעברות',Wallet],['players','הסקוואד',Users]];
const titles={home:'מבט על השולחן',sessions:'הישיבות שלי',stats:'סטטיסטיקות',debts:'חובות והעברות',players:'הסקוואד',notifications:'התראות ואישורים',settings:'הפרופיל שלי',admin:'ניהול ושקיפות'};
const statusLabel={active:'משחקים עכשיו',waiting:'מחכים לסקוואד',closed:'הסתיימה'};
function Avatar({user,size=''}){return <span className={`avatar color-${user?.color||0} ${size}`}>{user?.avatar?<img src={user.avatar} alt=""/>:user?.name?.slice(0,1)||'?'}</span>}
function Empty({title='עוד אין כאן פעילות',text='הערב הבא שלכם מתחיל כאן.',action}){return <div className="empty"><Spade size={36}/><h3>{title}</h3><p>{text}</p>{action}</div>}
function Money({value,signed=false}){return <b dir="ltr" className={signed?(value>0?'positive':value<0?'negative':'neutral'):''}>{money(value,signed)}</b>}
function Modal({title,children,onClose}){const ref=useRef();useEffect(()=>{ref.current.showModal();const previous=document.activeElement;return()=>previous?.focus?.();},[]);return <dialog ref={ref} onCancel={onClose} onClick={e=>e.target===ref.current&&onClose()}><div className="dialog-head"><h2>{title}</h2><button aria-label="סגירה" className="icon-button" onClick={onClose}><X/></button></div>{children}</dialog>}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function Chart({results=[],bars=false,small=false}){const [hover,setHover]=useState(null);let acc=0;const values=results.map(r=>bars?r.net:(acc+=r.net));const max=Math.max(...values,0),min=Math.min(...values,0),range=max-min||100;const y=v=>145-(v-min)/range*120;const points=values.map((v,i)=>[30+i*650/Math.max(values.length-1,1),y(v)]);const path=points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');if(!values.length)return <Empty title="הגרף שלכם עוד לפניכם" text="סיימו ישיבה כדי להתחיל לצבור תוצאות."/>;return <div className={`chart ${small?'small':''}`} dir="ltr"><svg viewBox="0 0 710 180" role="img" aria-label={bars?'רווח והפסד בכל ישיבה':'רווח מצטבר לאורך הישיבות'}><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#afe477" stopOpacity=".26"/><stop offset="1" stopColor="#afe477" stopOpacity="0"/></linearGradient></defs>{[25,65,105,145].map((v,i)=><g key={v}><line x1="30" x2="685" y1={v} y2={v} stroke="#2a3530" strokeDasharray="4 5"/><text x="28" y={v-5} fill="#89958b" fontSize="10">{Math.round((max-range*i/3)/100)} ₪</text></g>)}{bars?points.map(([x,yy],i)=><rect key={i} x={x-10} y={Math.min(y(0),yy)} width="20" rx="3" height={Math.max(Math.abs(y(0)-yy),2)} fill={values[i]>=0?'#b1e77d':'#ed8a87'} onMouseEnter={()=>setHover(i)} onMouseLeave={()=>setHover(null)}><title>{money(values[i],true)}</title></rect>):<><path d={`${path} L${points.at(-1)[0]},160 L30,160 Z`} fill="url(#chartFill)"/><path d={path} fill="none" stroke="#b1e77d" strokeWidth="3" strokeLinejoin="round"/>{points.map(([x,yy],i)=><circle key={i} cx={x} cy={yy} r="4" fill="#18231d" stroke="#b1e77d" strokeWidth="2" onMouseEnter={()=>setHover(i)} onMouseLeave={()=>setHover(null)}><title>{money(values[i],true)}</title></circle>)}</>}{hover!==null&&<g><rect x={Math.min(points[hover][0],580)} y="0" width="100" height="25" rx="5" fill="#b1e77d"/><text x={Math.min(points[hover][0],580)+50} y="17" textAnchor="middle" fontSize="12" fill="#152019">{money(values[hover],true)}</text></g>}<text x="30" y="178" fill="#87948b" fontSize="10">הישיבה הראשונה</text><text x="680" y="178" textAnchor="end" fill="#87948b" fontSize="10">הישיבה האחרונה</text></svg></div>}

function App(){
  const [initial]=useState(()=>{try{return load()}catch(e){return {state:emptyState(),mode:'error',actorId:null,error:e.message}}});
  const [state,setState]=useState(initial.state),[actorId,setActor]=useState(initial.actorId),[mode,setMode]=useState(initial.mode),[page,setPage]=useState(location.hash.slice(1).split('/')[0]||'home'),[modal,setModal]=useState(null),[error,setError]=useState(initial.error||''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[sessionMonth,setSessionMonth]=useState(''),[period,setPeriod]=useState('all'),[range,setRange]=useState({from:'',to:''}),[profileId,setProfileId]=useState(null),[selectedSession,setSelectedSession]=useState(null),[selectedDebt,setSelectedDebt]=useState(null),[cloud,setCloud]=useState(null),[cloudUser,setCloudUser]=useState(null),[cloudChecked,setCloudChecked]=useState(DEMO),[localPassword,setLocalPassword]=useState(()=>!initial.actorId||hasPassword(initial.actorId));
  const actor=state.users.find(u=>u.id===actorId),user=id=>state.users.find(u=>u.id===id);const stats=statistics(state,actorId);const mineDebts=debts(state,actorId),pay=mineDebts.filter(d=>d.amount>0).reduce((n,d)=>n+d.amount,0),receive=-mineDebts.filter(d=>d.amount<0).reduce((n,d)=>n+d.amount,0);const pending=state.requests.filter(r=>r.status==='pending'&&r.target===actorId);const openSessions=state.sessions.filter(s=>s.status!=='closed').sort((a,b)=>b.date.localeCompare(a.date)),active=openSessions.find(s=>s.players.includes(actorId)),joinable=!active&&openSessions[0];const mustChange=actor&&(mode==='cloud'?!actor.passwordSet:mode==='local'&&!localPassword);const mineSessions=state.sessions.filter(s=>s.players.includes(actorId)).sort((a,b)=>b.date.localeCompare(a.date));
  useEffect(()=>{const f=()=>setPage(location.hash.slice(1).split('/')[0]||'home');addEventListener('hashchange',f);const sync=e=>{if(e.key==='phlop:data:v1'&&mode!=='cloud')try{setState(load().state)}catch(err){setError(err.message)}};addEventListener('storage',sync);return()=>{removeEventListener('hashchange',f);removeEventListener('storage',sync)}},[mode]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(t)},[toast]);
  useEffect(()=>{if(DEMO)return;import('./cloud').then(m=>m.connectCloud({onAuth:u=>{setCloudUser(u);if(!u){setActor(null);setState(emptyState());setMode("cloud")}},onState:setState,onError:e=>setError(e.message)})).then(c=>c&&setCloud(c)).catch(e=>setError(e.message)).finally(()=>setCloudChecked(true));},[]);
  useEffect(()=>{if(cloudUser&&cloud){setMode('cloud');setActor(cloudUser.uid);cloud.subscribe();}},[cloudUser,cloud]);
  const go=p=>{window.scrollTo({top:0,behavior:'instant'});setPage(p);location.hash=p;setSearch('');setSelectedSession(null);setSelectedDebt(null);};
  async function act(action,keep=false){if(busy)return false;setBusy(true);setError('');try{const id=uid();if(mode==='cloud'){await cloud.send(action,id)}else setState(await mutate(actorId,action,id));if(!keep)setModal(null);setToast('נשמר. הכול מעודכן ✓');return true}catch(e){setError(e.message);return false}finally{setBusy(false)}}
  function switchActor(id){if(mode!=='demo')return;setActor(id);save({...load(),actorId:id});setSelectedSession(null);setSelectedDebt(null);}
  async function login(phone,password){setError('');try{if(cloud)return await cloud.login(phone,password);const u=state.users.find(u=>u.phone===normalizePhone(phone));if(!u||!await checkPassword(u.id,password))throw Error('מספר הטלפון או הסיסמה שגויים');save({...load(),actorId:u.id});setLocalPassword(hasPassword(u.id));setActor(u.id);go('home')}catch(e){setError(e.message)}}
  async function changePassword(password){setError('');try{if(mode==='cloud')await cloud.changePassword(password);else{await setPassword(actorId,password);if(!actor.passwordSet)setState(await mutate(actorId,{type:'password'},uid()));setLocalPassword(true)}setToast('הסיסמה עודכנה ✓')}catch(e){setError(e.message)}}
  function logout(){if(mode==='cloud')return cloud.logout().then(()=>location.reload());save({...load(),actorId:null});setActor(null);}
  const openSession=s=>{go('sessions');setSelectedSession(s.id)};
  const selected=state.sessions.find(s=>s.id===selectedSession);
  function sessionRows(items,viewerId=actorId){return items.length?<div className="table-wrap"><table><thead><tr><th>תאריך</th><th>מיקום</th><th>שחקנים</th><th>{viewerId===actorId?"כניסות שלי":"סך כניסות"}</th><th>{viewerId===actorId?"התוצאה שלי":"תוצאה"}</th><th>סטטוס</th><th/></tr></thead><tbody>{items.map(s=>{const r=s.results.find(r=>r.userId===viewerId);return <tr key={s.id} onClick={()=>openSession(s)}><td><button className="table-title" onClick={()=>openSession(s)}><span className="session-icon"><Spade size={18}/></span>{date(s.date)}</button></td><td className="muted">{place(state,s)||'—'}</td><td>{s.players.length} שחקנים</td><td><Money value={buyTotal(s,viewerId)}/></td><td>{r?<Money value={r.net} signed/>:<span className="muted">—</span>}</td><td><span className={`badge ${s.status}`}>{statusLabel[s.status]}</span></td><td><ChevronLeft size={17}/></td></tr>})}</tbody></table></div>:<Empty title="עוד אין ישיבות" action={<button className="primary" onClick={()=>setModal({type:'create'})}><Plus size={17}/>ישיבה חדשה</button>}/>}
  const sectionTitle=(title,sub,action)=><div className="section-title"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{action}</div>;
  const miniLink=(text,p)=><button className="text-button" onClick={()=>go(p)}>{text}<ArrowLeft size={15}/></button>;

  if(!actor||mustChange){return <div className="welcome"><div className="welcome-art"><div className="brand"><span className="brand-icon">♠</span><b>פלופ<span>FLOP</span></b></div><div className="welcome-copy"><span className="eyebrow">GOOD FRIENDS. GREAT HANDS.</span><h1><em>החשבונות? עלינו.</em></h1><p>הבית של ערבי הפוקר שלכם.<br/>כל הכניסות, התוצאות והחובות — במקום אחד.</p><div className="playing-cards"><div className="playing-card">A<span>♠</span><small>A</small></div><div className="playing-card red-card">K<span>♥</span><small>K</small></div><div className="playing-card">Q<span>♣</span><small>Q</small></div></div></div><p className="tiny">רק הסקוואד, הקלפים, ועוד ערב ששווה לזכור.</p></div><div className="welcome-form">{mustChange?<><span className="badge">כניסה ראשונה</span><h2>היי, {actor.name}</h2><p>בוחרים סיסמה אישית חדשה. מהפעם הבאה הכניסה אוטומטית.</p>{error&&<div role="alert" className="alert danger">{error}</div>}<PasswordForm onSubmit={changePassword}/><button className="text-button" onClick={logout}><LogOut size={15}/>יציאה</button></>:<><span className="badge">ברוכים הבאים לשולחן</span><h2>יאללה, מתחילים?</h2><p>כל ערב טוב מתחיל בסקוואד הנכון.</p>{error&&<div role="alert" className="alert danger">{error}</div>}<Login onLogin={login} disabled={!cloudChecked}/>{!DEMO&&<><div className="separator">זמני, לבדיקה</div><button className="secondary wide" onClick={()=>location.assign('?demo#home')}>מעבר לנתונים סינתטיים<Play size={16}/></button></>}</>}<p className="footnote">פלופ מתעדת יתרות וחובות. העברת הכסף נעשית ביניכם.</p></div></div>}

  return <div className="app-shell"><aside className="sidebar"><a className="brand" href="#home" onClick={()=>go('home')}><span className="brand-icon">♠</span><b>פלופ<span>FLOP</span></b></a><div className="group-label"><span className="online-dot"/>השולחן של הסקוואד<small>המעגל שלנו</small></div><nav>{nav.map(([key,label,Icon])=><button className={page===key?'nav-item selected':'nav-item'} onClick={()=>go(key)} key={key}><Icon size={20}/>{label}{key==='debts'&&pending.length>0&&<span className="count">{pending.length}</span>}</button>)}</nav><div className="sidebar-bottom">{actor.role==='admin'&&<button className={`nav-item ${page==='admin'?'selected':''}`} onClick={()=>go('admin')}><ShieldCheck size={20}/>ניהול ושקיפות</button>}<button className={`nav-item ${page==='settings'?'selected':''}`} onClick={()=>go('settings')}><Settings size={20}/>הפרופיל וההגדרות שלי</button><button className="sidebar-profile" onClick={()=>go('settings')}><Avatar user={actor}/><span><strong>{actor.name}</strong><small>{actor.role==='admin'?'מנהל הקבוצה':'חבר בשולחן'}</small></span><ChevronLeft size={17}/></button></div></aside>
  <div className="workspace"><header className="topbar"><div className="breadcrumb">המרחב שלנו <ChevronLeft size={14}/><strong>{titles[page]}</strong></div><div className="topbar-actions"><div className={`sync-state ${mode==='cloud'?'':'local'}`}><span className="online-dot"/>{mode==='demo'?'מצב הדגמה':mode==='cloud'?'מחוברים בזמן אמת':'שמירה במכשיר'}</div><button className="icon-button notification-button" aria-label="התראות ואישורים" onClick={()=>go('notifications')}><Bell size={20}/>{pending.length>0&&<span/>}</button><Avatar user={actor}/></div></header>
  <main><div className="mode-strip"><Info size={14}/>{mode==='demo'?'נתוני הדגמה בלבד · אפשר להתנסות בכל הפעולות ולהחליף שחקן בפרופיל.':mode==='cloud'?'כל העדכונים משותפים לחברי הקבוצה.':'מצב מקומי · הנתונים נשמרים במכשיר הזה בלבד. אישורים כאן הם תיעוד משותף במכשיר.'}{mode==='demo'&&import.meta.env.MODE!=='demo'?<button onClick={()=>location.assign(location.pathname)}>חזרה לאתר האמיתי</button>:mode!=='cloud'&&<button onClick={()=>go('settings')}>הגדרות וחיבור</button>}</div>
  {error&&<div role="alert" className="alert danger">{error}<button className="icon-button" onClick={()=>setError('')} aria-label="סגירת הודעה"><X size={16}/></button></div>}
  {page==='home'&&<><div className="page-heading"><div><div className="eyebrow">{new Intl.DateTimeFormat('he-IL',{weekday:'long',day:'numeric',month:'long',timeZone:'Asia/Jerusalem'}).format(new Date())}</div><h1>היי, {actor.name}<span className="wave">✌</span></h1></div><div className="heading-actions"><button className="primary" onClick={()=>setModal({type:'create'})}><Plus size={18}/>ישיבה חדשה</button></div></div>
  <div className="metric-grid"><Metric label="הרווח שלי החודש" value={statistics(state,actorId,israelDay(new Date()).slice(0,7)+'-01').total} signed icon={TrendingUp} special/><Metric label="רווח בכל הזמנים" value={stats.total} signed icon={ChartNoAxesCombined} note={`מתוך ${stats.count} משחקים`}/><Metric label="חייבים לי" value={receive} icon={ArrowDownLeft} note={`${mineDebts.filter(d=>d.amount<0).length} חברים עם יתרה פתוחה`} green/><Metric label="אני חייב" value={pay} icon={ArrowUpLeft} note="נסגור את זה לפני הערב הבא"/></div>
  <div className="dashboard-grid"><section className="panel live-panel">{sectionTitle('השולחן הפעיל',null,<span className={`badge ${active||joinable?"active":""}`}>{active||joinable?"LIVE":"מחכים לערב הבא"}</span>)}{active||joinable?(t=><><div className="live-title"><div><h2>{date(t.date)}</h2><p>{place(state,t)&&<><MapPin size={14}/>{place(state,t)}<span>•</span></>}<Clock size={14}/>{date(t.date,true).split(' ').at(-1)}<Elapsed start={t.date} status={t.status}/><span>•</span>המארח: {user(t.host)?.name}</p></div><div className="card-symbol">♠</div></div><div className="live-summary"><div><span>סך הכניסות בשולחן</span><strong dir="ltr">{money(t.buyins.reduce((n,b)=>n+b.amount,0))}</strong></div><div><span>הכניסות שלי</span><strong dir="ltr">{money(buyTotal(t,actorId))}</strong></div></div><div className="live-footer"><div className="avatar-stack">{t.players.slice(0,5).map(id=><Avatar key={id} user={user(id)}/>)}<span>{t.players.length} בשולחן</span></div>{active?<button className="primary" onClick={()=>openSession(t)}>לשולחן<ArrowLeft size={16}/></button>:<button className="primary" onClick={()=>setModal({type:'join',session:t})}>הצטרפות לשולחן<ArrowLeft size={16}/></button>}</div></>)(active||joinable):<Empty title="השולחן מחכה לכם" text="פותחים ערב חדש ומזמינים את הסקוואד." action={<button className="primary" onClick={()=>setModal({type:'create'})}>בואו נתחיל<Plus size={16}/></button>}/>}</section>
  <section className="panel chart-panel">{sectionTitle('לאורך הדרך','הרווח המצטבר שלך',miniLink('כל הסטטיסטיקות','stats'))}<div className="chart-summary"><Money value={stats.total} signed/><span className="subtle-pill">{stats.winRate}% משחקים ברווח</span></div><Chart results={stats.results} small/></section>
  <section className="panel recent-panel">{sectionTitle('המשחקים האחרונים',null,miniLink('לכל הישיבות','sessions'))}{sessionRows(mineSessions.slice(0,4))}</section>
  <section className="panel debts-panel">{sectionTitle('בין חברים','היתרות הפתוחות שלך',miniLink('לכל החובות','debts'))}{mineDebts.length?mineDebts.slice(0,3).map(d=><button className="debt-mini" key={d.user.id} onClick={()=>{go('debts');setSelectedDebt(d.user.id)}}><Avatar user={d.user}/><span><strong>{d.user.name}</strong><small>{d.amount>0?'אני חייב':'חייב לי'}</small></span><Money value={Math.abs(d.amount)}/><ChevronLeft size={16}/></button>):<Empty title="הכול סגור ביניכם" text="אין כרגע חובות פתוחים."/>}{pending.length>0&&<button className="pending-note" onClick={()=>go('notifications')}><Bell size={17}/>{pending.length} בקשות מחכות לאישור שלך<ArrowLeft size={15}/></button>}</section></div>
  </>}

  {page==='sessions'&&<><PageHeading title={selected?date(selected.date):'כל ערב והסיפור שלו'} sub={selected?[place(state,selected),`נפתח ב־${date(selected.date,true).split(' ').at(-1)}`,`מארח: ${user(selected.host)?.name}`].filter(Boolean).join(' · '):'המשחקים שלכם, מהיד הראשונה ועד החשבון האחרון.'} action={<button className="primary" onClick={()=>setModal({type:'create'})}><Plus size={18}/>ישיבה חדשה</button>}/>{selected?<><button className="text-button back" onClick={()=>setSelectedSession(null)}><ArrowRight size={16}/>לכל הישיבות</button><div className="session-top"><span className={`badge ${selected.status}`}>{statusLabel[selected.status]}</span>{selected.status==='active'&&(actor.role==='admin'||selected.host===actorId)&&<button className="primary" onClick={()=>setModal({type:'close',session:selected})}><CheckCheck size={17}/>סיים את הערב</button>}{selected.status==='waiting'&&(actor.role==='admin'||selected.host===actorId)&&<button className="primary" onClick={()=>act({type:'start',sessionId:selected.id})}><Play size={16}/>מתחילים לשחק</button>}{selected.status==='closed'&&actor.role==='admin'&&<button className="secondary" onClick={()=>setModal({type:'close',session:selected,correction:true})}>תיקון תוצאות</button>}</div><div className="metric-grid three"><Metric label="הכסף בשולחן" value={selected.buyins.reduce((n,b)=>n+b.amount,0)} icon={Wallet}/><Metric label="שחקנים בשולחן" text={selected.players.length} icon={Users}/><Metric label="הכניסות שלי" value={buyTotal(selected,actorId)} icon={Spade}/></div><section className="panel">{sectionTitle('משתתפים')}<div className="players-grid">{[...selected.players].sort((a,b)=>(selected.results.find(r=>r.userId===b)?.net||0)-(selected.results.find(r=>r.userId===a)?.net||0)).map(id=>{const r=selected.results.find(r=>r.userId===id);return <div className={`player-card ${id===actorId?'me':''}`} key={id}><div className="player-name"><Avatar user={user(id)}/><div><strong>{user(id)?.name}{id===actorId&&' (אני)'}</strong><small>{selected.host===id?'מארח הערב':'בשולחן'}</small></div>{selected.host===actorId&&id!==actorId&&selected.status!=='closed'&&<button className="icon-button" title="העברת אירוח" aria-label={`העברת אירוח אל ${user(id)?.name}`} onClick={()=>setModal({type:'confirm',title:'העברת ניהול הישיבה',text:`${user(id)?.name} יוכל לנהל ולסגור את הישיבה.`,action:{type:'host',sessionId:selected.id,userId:id}})}><ShieldCheck size={17}/></button>}</div><div className="player-total"><span>סך כניסות</span><Money value={buyTotal(selected,id)}/></div><small>{selected.buyins.filter(b=>b.userId===id).length} כניסות</small>{r?<div className="result-box"><span>תוצאה סופית</span><Money value={r.net} signed/>{r.adjustment!==0&&<small>כולל התאמה: {money(r.adjustment,true)}</small>}</div>:selected.status==='active'&&(id===actorId||selected.host===actorId||actor.role==='admin')?<button className="secondary wide" onClick={()=>setModal({type:'buyin',session:selected,userId:id})}><Plus size={16}/>הוסף כניסה</button>:null}</div>})}</div></section>{selected.status==='closed'&&<section className="panel">{sectionTitle('תוכנית ההעברות שאושרה','העברות אלו יוצרות חובות. אישורי תשלום נמצאים בעמוד החובות.')}<TransferList transfers={selected.transfers} user={user}/></section>}<section className="panel">{sectionTitle('כל כניסה מתועדת')}<div className="activity-list">{[...selected.buyins].reverse().map(b=><div className="activity" key={b.id}><Avatar user={user(b.userId)}/><div><strong>{user(b.userId)?.name} הוסיף כניסה</strong><small>{date(b.date,true)}</small></div><Money value={b.amount}/></div>)}</div></section></>:<><div className="toolbar"><div className="search"><Search size={18}/><input placeholder="חיפוש לפי שחקן או מיקום…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="סינון ישיבות" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">כל הישיבות</option><option value="active">ישיבות פעילות</option><option value="win">משחקים ברווח</option><option value="loss">משחקים בהפסד</option></select><input type="month" aria-label="חודש הישיבה" value={sessionMonth} onChange={e=>setSessionMonth(e.target.value)}/></div><section className="panel">{sessionRows(state.sessions.filter(s=>(s.players.includes(actorId)||s.status!=='closed')&&(place(state,s).includes(search)||date(s.date).includes(search)||s.players.some(id=>user(id)?.name.includes(search)))&&(!sessionMonth||month(s.date)===sessionMonth)&&(filter==='all'||filter==='active'&&s.status!=='closed'||filter==='win'&&s.results.find(r=>r.userId===actorId)?.net>0||filter==='loss'&&s.results.find(r=>r.userId===actorId)?.net<0)).sort((a,b)=>b.date.localeCompare(a.date)))}</section></>}</>}

  {page==='debts'&&<><PageHeading title={selectedDebt?`החשבון עם ${user(selectedDebt)?.name}`:'נשארים חברים. סוגרים חשבון.'} action={<button className="primary" onClick={()=>setModal({type:'request',kind:'manual'})}><Plus size={17}/>הוסף חוב</button>}/><div className="metric-grid"><Metric label="חייבים לי" value={receive} icon={ArrowDownLeft} green/><Metric label="אני חייב" value={pay} icon={ArrowUpLeft}/><Metric label="המאזן שלי" value={receive-pay} signed icon={Wallet}/><Metric label="מחכים לאישור שלי" text={pending.length} icon={Bell}/></div>{selectedDebt?<><button className="text-button back" onClick={()=>setSelectedDebt(null)}><ArrowRight size={16}/>לכל החובות</button><section className="panel"><div className="debt-detail-head"><Avatar user={user(selectedDebt)} size="large"/><div><h2>{user(selectedDebt)?.name}</h2><p>{balance(state,actorId,selectedDebt)>0?'אני חייב':'חייב לי'} <Money value={Math.abs(balance(state,actorId,selectedDebt))}/></p></div>{balance(state,actorId,selectedDebt)!==0&&<button className="primary" onClick={()=>setModal({type:'request',kind:'payment',other:selectedDebt})}>דיווח על תשלום</button>}</div>{state.entries.filter(e=>[e.from,e.to].includes(actorId)&&[e.from,e.to].includes(selectedDebt)).map(e=><div key={e.id} className="activity"><span className="session-icon">{e.kind==='payment'?<Check size={18}/>:<Wallet size={18}/>}</span><div><strong>{e.kind==='payment'?'תשלום שאושר':e.kind==='correction'?'תיקון מתועד':e.kind==='manual'?'חוב ידני':'חוב מישיבת פוקר'}</strong><small>{date(e.date,true)} {e.reason&&`· ${e.reason}`}</small>{e.sessionId&&<button className="text-button" onClick={()=>openSession(state.sessions.find(s=>s.id===e.sessionId))}>{(s=>s&&`ערב ${sessionTitle(state,s)}`)(state.sessions.find(s=>s.id===e.sessionId))}<ArrowLeft size={13}/></button>}</div><Money value={e.from===actorId?-e.amount:e.amount} signed/></div>)}</section></>:<><div className="two-columns">{[false,true].map(owe=><section className="panel" key={String(owe)}>{sectionTitle(owe?'אני חייב':'חייבים לי',owe?'להחזיר, לאשר ולהמשיך לשחק':'כל היתרות, גם מהחודשים הקודמים')}{mineDebts.filter(d=>owe?d.amount>0:d.amount<0).map(d=><div className="debt-card" key={d.user.id}><button className="debt-mini" onClick={()=>setSelectedDebt(d.user.id)}><Avatar user={d.user}/><span><strong>{d.user.name}</strong><small>יתרה מצטברת נטו</small></span><Money value={Math.abs(d.amount)}/><ChevronLeft size={16}/></button><div className="debt-actions"><button className="secondary" onClick={()=>setModal({type:'request',kind:'payment',other:d.user.id})}>דיווח על תשלום<Check size={15}/></button>{owe&&d.user.phone&&<BitLink to={d.user} amount={d.amount} notify={setToast}/>}{!owe&&<button className="text-button" onClick={()=>setModal({type:'confirm',title:'שליחת תזכורת ידידותית',text:`התזכורת תופיע אצל ${d.user.name} במרכז ההתראות.`,action:{type:'remind',userId:d.user.id}})}><Bell size={15}/>תזכורת</button>}</div>{state.requests.some(r=>r.status==='pending'&&[r.from,r.to].includes(actorId)&&[r.from,r.to].includes(d.user.id))&&<span className="pending-label">בקשה ממתינה לאישור</span>}</div>)}{!mineDebts.some(d=>owe?d.amount>0:d.amount<0)&&<Empty title="הכול מסודר" text="אין יתרות פתוחות בקטגוריה הזו."/>}</section>)}</div><section className="panel">{sectionTitle('הבקשות שלי','אישור, דחייה ותשלום חלקי — הכול נשמר בהיסטוריה')}<Requests state={state} actorId={actorId} user={user} onResolve={(r,status)=>setModal({type:'confirm',title:status==='approved'?'אישור הפעולה':status==='rejected'?'דחיית הבקשה':'ביטול בקשה',text:`${r.kind==='payment'?'תשלום':'חוב ידני'} בסך ${money(r.amount)}, מ${user(r.from)?.name} ל${user(r.to)?.name}. ${status==='approved'?'האישור יעדכן את יתרת החוב.':'יתרת החוב לא תשתנה.'}`,action:{type:'resolve',id:r.id,status}})}/></section></>}</>}

  {page==='stats'&&<><PageHeading title="המספרים מאחורי הקלפים" sub="כל ערב הוא סיפור. ביחד הם כבר מגמה."/><div className="toolbar"><div className="tabs">{[['all','כל הזמנים'],['month','החודש'],['last','חודש קודם'],['year','השנה'],['custom','טווח אישי']].map(([key,label])=><button key={key} className={period===key?'active':''} onClick={()=>setPeriod(key)}>{label}</button>)}</div>{period==='custom'&&<><input aria-label="מתאריך" type="date" value={range.from} onChange={e=>setRange({...range,from:e.target.value})}/><input aria-label="עד תאריך" type="date" value={range.to} onChange={e=>setRange({...range,to:e.target.value})}/></>}</div><StatsView state={state} actorId={actorId} period={period} range={range} user={user}/><MonthlySummary state={state}/></>}

  {page==='players'&&<><PageHeading title="הסקוואד שלנו"/><div className="players-grid">{state.users.map(u=>{const st=statistics(state,u.id);return <button className="profile-card" key={u.id} onClick={()=>setProfileId(profileId===u.id?null:u.id)}><Avatar user={u} size="large"/><h2>{u.name}</h2><small>בשולחן מאז {date(u.joined)}</small><Money value={st.total} signed/><div className="profile-metrics"><span><b>{st.count}</b>משחקים</span><span><b>{st.winRate}%</b>ברווח</span><span><b>{money(st.best)}</b>שיא לערב</span></div></button>})}</div>{profileId&&<section className="panel">{sectionTitle(`המשחקים של ${user(profileId)?.name}`)}{sessionRows(state.sessions.filter(s=>s.players.includes(profileId)&&s.status==='closed'),profileId)}</section>}</>}

  {page==='notifications'&&<><PageHeading title="מה חדש בשולחן?" sub="קודם מטפלים בבקשות, אחר כך חוזרים לקלפים."/><section className="panel">{sectionTitle('ממתינים לאישור שלך',`${pending.length} בקשות פתוחות`)}<Requests state={{...state,requests:pending}} actorId={actorId} user={user} onResolve={(r,status)=>setModal({type:'confirm',title:status==='approved'?'אישור הבקשה':'דחיית הבקשה',text:`${user(r.from)?.name} → ${user(r.to)?.name}: ${money(r.amount)}. ${r.reason}`,action:{type:'resolve',id:r.id,status}})}/></section><section className="panel">{sectionTitle('עדכונים אחרונים')}{state.notifications.filter(n=>n.userId===actorId).reverse().slice(0,50).map(n=><div className="activity" key={n.id}><span className="session-icon"><Bell size={18}/></span><div><strong>{n.text}</strong><small>{date(n.date,true)}</small></div></div>)}</section></>}

  {page==='settings'&&<><PageHeading title="המקום שלך בשולחן" sub="פרופיל, נתונים והעדפות — הכול כאן."/><div className="two-columns"><section className="panel">{sectionTitle('הפרופיל שלי')}<ProfileForm key={actorId} actor={actor} busy={busy} submit={action=>act(action,true)}/>{mode==='demo'&&<><hr/><Field label="בחירת שחקן בהדגמה"><select value={actorId} onChange={e=>switchActor(e.target.value)}>{state.users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field></>}<hr/><h3>החלפת סיסמה</h3><PasswordForm onSubmit={changePassword} compact/></section><section className="panel">{sectionTitle('המידע שלכם','נתוני המשחק אינם מועלים למאגר GitHub.')}<div className="notice"><ShieldCheck/><div><strong>{mode==='cloud'?'חיבור קבוצתי פעיל':'שמירה מקומית במכשיר'}</strong><p>{mode==='cloud'?'המידע משותף בין המשתתפים ומגובה ביומן הפעולות.':'מחיקת נתוני הדפדפן עלולה למחוק את המידע. מומלץ להוריד גיבוי אחרי כל ערב.'}</p></div></div><div className="settings-buttons"><button className="secondary" onClick={()=>download(JSON.stringify({schema:1,exportedAt:new Date().toISOString(),state},null,2),'flop-backup.json')}><Download size={17}/>הורדת גיבוי</button>{mode!=='cloud'&&<label className="secondary file-button"><Upload size={17}/>שחזור מגיבוי<input type="file" accept="application/json" hidden onChange={async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>10000000)throw Error('הקובץ גדול מדי');const data=JSON.parse(await file.text());if(data.schema!==1||!Array.isArray(data.state?.audit))throw Error('קובץ גיבוי לא תקין');const rebuilt=replay(data.state.audit.map(a=>({id:a.id,actorId:a.actorId,date:a.date,action:a.action})));if(rebuilt.rejected.length||JSON.stringify(rebuilt.state)!==JSON.stringify(data.state))throw Error('הגיבוי אינו תואם את יומן הפעולות');setModal({type:'restore',state:rebuilt.state});}catch(e){setError(e.message)}}}/></label>}</div><hr/><div className="settings-buttons"><button className="secondary" onClick={logout}><LogOut size={17}/>יציאה מהחשבון</button>{!DEMO&&<button className="secondary" onClick={()=>location.assign('?demo#home')}><Play size={17}/>נתונים סינתטיים (זמני)</button>}</div></section></div>{mode==='demo'&&<section className="panel"><h3>מתחילים את ההדגמה מחדש?</h3><p className="muted">כל השינויים שביצעת בהדגמה יימחקו והנתונים הסינטטיים ייטענו מחדש.</p><button className="secondary" onClick={()=>setModal({type:'reset'})}>איפוס נתוני ההדגמה</button></section>}</>}

  {page==='admin'&&actor.role==='admin'&&<><PageHeading title="ניהול ושקיפות" sub="כל פעולה משאירה עקבות. אין מחיקה שקטה של כסף."/><section className="panel">{sectionTitle('הרשאות הסקוואד')}{state.users.map(u=><div className="activity" key={u.id}><Avatar user={u}/><strong>{u.name}</strong><select aria-label={`הרשאה של ${u.name}`} value={u.role} disabled={u.id===actorId} onChange={e=>setModal({type:'confirm',title:'עדכון הרשאות',text:`שינוי הרשאות עבור ${u.name}`,action:{type:'role',userId:u.id,role:e.target.value}})}><option value="user">משתמש</option><option value="host">מארח</option>{u.role==='admin'&&<option value="admin">אדמין</option>}</select>{mode==='local'&&u.id!==actorId&&<button className="text-button" onClick={()=>{resetPassword(u.id);setToast(`הסיסמה של ${u.name} אופסה לסיסמה הראשונית`)}}><KeyRound size={14}/>איפוס סיסמה</button>}</div>)}</section><section className="panel">{sectionTitle('יומן הפעולות','הפעולות המקוריות נשמרות גם לאחר תיקון')}<div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="חיפוש פעולה או שחקן…"/></div>{[...state.audit].reverse().filter(a=>!search||JSON.stringify(a.action).includes(search)||user(a.actorId)?.name.includes(search)).slice(0,100).map(a=><details key={a.id} className="audit"><summary><span><FileClock size={15}/>{user(a.actorId)?.name} · {({register:'הצטרפות',password:'בחירת סיסמה',create:'יצירת ישיבה',join:'כניסה לשולחן',buyin:'כניסה נוספת',close:'סגירת ישיבה',request:'בקשת חוב / תשלום',resolve:'טיפול בבקשה',correct:'תיקון תוצאות',profile:'עדכון פרופיל',role:'שינוי הרשאות',remind:'תזכורת',host:'העברת אירוח',start:'תחילת משחק'})[a.action.type]}</span><small>{date(a.date,true)}</small></summary><pre dir="ltr">{JSON.stringify({action:a.action,before:a.before,after:a.after},null,2)}</pre></details>)}</section></>}
  </main><footer className="footer"><span>פלופ</span></footer></div>
  <nav className="mobile-nav">{nav.slice(0,4).map(([key,label,Icon])=><button className={page===key?'selected':''} key={key} onClick={()=>go(key)}><Icon size={21}/><span>{key==='home'?'בית':key==='sessions'?'ישיבות':key==='stats'?'סטטיסטיקות':'חובות'}</span></button>)}<button className={['settings','players','admin'].includes(page)?'selected':''} onClick={()=>setModal({type:'menu'})}><Menu size={21}/><span>עוד</span></button></nav>
  {toast&&<div className="toast" role="status"><Check size={18}/>{toast}</div>}
  {modal&&<Modal title={modal.title||({create:'פותחים שולחן חדש',join:'מצטרפים לסקוואד',buyin:'עוד כניסה, עוד הזדמנות',close:modal.correction?'תיקון תוצאות מתועד':'סוגרים את הערב',request:modal.kind==='manual'?'חוב חדש בין חברים':'דיווח על תשלום',restore:'שחזור נתונים',reset:'מתחילים מחדש',menu:'עוד בפלופ'})[modal.type]} onClose={()=>!busy&&setModal(null)}>{error&&<div className="alert danger" role="alert">{error}</div>}
  {modal.type==='create'&&<CreateForm state={state} actorId={actorId} busy={busy} submit={act}/>}
  {modal.type==='buyin'&&<AmountForm label={`כניסה עבור ${user(modal.userId)?.name}`} submit={n=>act({type:'buyin',sessionId:modal.session.id,userId:modal.userId,amount:n})} busy={busy}/>}
  {modal.type==='join'&&<JoinForm label={sessionTitle(state,modal.session)} session={modal.session} submit={act} busy={busy}/>}
  {modal.type==='close'&&<CloseForm session={state.sessions.find(s=>s.id===modal.session.id)} user={user} submit={act} correction={modal.correction} busy={busy}/>}
  {modal.type==='request'&&<RequestForm state={state} actorId={actorId} kind={modal.kind} other={modal.other} submit={act} busy={busy}/>}
  {modal.type==='confirm'&&<><p>{modal.text}</p><div className="notice"><Info size={18}/>{mode==='cloud'?'הפעולה תירשם ותעודכן אצל המשתתפים.':'הפעולה תירשם במכשיר זה.'}</div><div className="dialog-actions"><button className="primary" disabled={busy} onClick={()=>act(modal.action)}>אישור הפעולה</button><button className="secondary" onClick={()=>setModal(null)}>חזרה</button></div></>}
  {modal.type==='restore'&&<><p>הגיבוי מכיל {modal.state.sessions.length} ישיבות ו־{modal.state.users.length} שחקנים. השחזור יחליף את הנתונים המקומיים הנוכחיים.</p><button className="primary" onClick={()=>{try{save({state:modal.state,mode,actorId:modal.state.users.some(u=>u.id===actorId)?actorId:null});location.reload()}catch(e){setError(e.message)}}}>אישור החלפה ושחזור</button></>}
  {modal.type==='reset'&&<><p>כל מה שהוספת בהדגמה יימחק, ונתוני ההדגמה המקוריים ייטענו מחדש.</p><button className="primary" onClick={()=>{try{startDemo();location.reload()}catch(e){setError(e.message)}}}>איפוס נתוני ההדגמה</button></>}
  {modal.type==='menu'&&<div className="mobile-menu">{[['players','הסקוואד',Users],['settings','הפרופיל שלי',Settings],...(actor.role==='admin'?[['admin','ניהול ושקיפות',ShieldCheck]]:[])].map(([p,label,Icon])=><button key={p} className="secondary" onClick={()=>{go(p);setModal(null)}}><Icon size={18}/>{label}</button>)}</div>}
  </Modal>}</div>
}

function Metric({label,value,text,signed,icon:Icon,note,special,green}){return <div className={`metric ${special?'highlight':''}`}><div className="metric-label"><span>{label}</span><Icon size={18}/></div><div className={`metric-value ${green?'positive':''}`}>{text??<Money value={value} signed={signed}/>}</div>{note&&<small>{note}</small>}</div>}
function PageHeading({title,sub,action}){return <div className="page-heading"><div><h1>{title}</h1><p>{sub}</p></div>{action}</div>}
function TransferList({transfers,user}){return transfers.length?<div className="transfers">{transfers.map((t,i)=><div className="transfer" key={i}><Avatar user={user(t.from)}/><strong>{user(t.from)?.name}</strong><ArrowLeft size={18}/><Avatar user={user(t.to)}/><strong>{user(t.to)?.name}</strong><Money value={t.amount}/></div>)}</div>:<p className="muted">כולם מאוזנים. אין צורך בהעברות.</p>}
function Requests({state,actorId,user,onResolve}){const rs=state.requests.filter(r=>[r.from,r.to].includes(actorId)).sort((a,b)=>(a.status==='pending'?-1:1)-(b.status==='pending'?-1:1)||b.date.localeCompare(a.date));return rs.length?rs.map(r=><div className="request" key={r.id}><div className="request-info"><Avatar user={user(r.initiator)}/><div><strong>{r.kind==='manual'?'בקשה להוספת חוב':'דיווח על תשלום'} · {money(r.amount)}</strong><p>{user(r.from)?.name} ← משלם ל{user(r.to)?.name}</p><small>{r.reason} · {date(r.date)}</small></div><span className={`badge ${r.status}`}>{{pending:'ממתינה',approved:'אושרה',rejected:'נדחתה',cancelled:'בוטלה'}[r.status]}</span></div>{r.status==='pending'&&<div className="request-actions">{r.target===actorId?<><button className="primary" onClick={()=>onResolve(r,'approved')}><Check size={16}/>אישור</button><button className="secondary" onClick={()=>onResolve(r,'rejected')}><X size={16}/>דחייה</button></>:<button className="text-button" onClick={()=>onResolve(r,'cancelled')}>ביטול הבקשה שלי</button>}</div>}</div>):<Empty title="אין בקשות שממתינות לך" text="אפשר לחזור לשולחן בראש שקט."/>}

function AmountForm({label,submit,busy}){const [value,set]=useState('100'),[error,setError]=useState('');return <form onSubmit={e=>{e.preventDefault();try{submit(cents(value))}catch(e){setError(e.message)}}}><p>{label}</p><div className="amount-presets">{[50,100,200].map(v=><button type="button" key={v} className={value===String(v)?'selected':''} onClick={()=>set(String(v))}>{v} ₪</button>)}</div><Field label="סכום הכניסה (₪)"><input inputMode="decimal" value={value} onChange={e=>set(e.target.value)} required/></Field>{error&&<p className="negative">{error}</p>}<button className="primary wide" disabled={busy}>אישור הוספת כניסה</button><p className="footnote">הכניסה תתווסף לסכום שלך ותירשם ביומן.</p></form>}
function CreateForm({state,actorId,submit,busy}){const hosts=state.users.filter(canHost),[where,setWhere]=useState(hosts.some(u=>u.id===actorId)?actorId:hosts[0]?.id||'other'),[error,setError]=useState('');return <form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);submit({type:'create',id:uid(),amount:cents(f.get('amount')),date:new Date().toISOString(),...(where==='other'?{location:f.get('location')}:{locationUserId:where})})}catch(e){setError(e.message)}}}><Field label="מיקום הישיבה"><select value={where} onChange={e=>setWhere(e.target.value)}>{hosts.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}<option value="other">אחר</option></select></Field>{where==='other'&&<Field label="איפה משחקים?"><input name="location" minLength="2" maxLength="60" required autoFocus/></Field>}<Field label="הכניסה הראשונה שלי (₪)"><input name="amount" inputMode="decimal" defaultValue="100" required/></Field>{error&&<p className="negative">{error}</p>}<button className="primary wide" disabled={busy}>פותחים שולחן<Spade size={17}/></button></form>}
function JoinForm({label,session,submit,busy}){const [error,setError]=useState('');return <form onSubmit={e=>{e.preventDefault();try{submit({type:'join',sessionId:session.id,amount:cents(new FormData(e.currentTarget).get('amount'))})}catch(e){setError(e.message)}}}><p className="muted">{label}</p><Field label="סכום הכניסה הראשונה (₪)"><input name="amount" inputMode="decimal" defaultValue="100" required/></Field>{error&&<p className="negative">{error}</p>}<button className="primary wide" disabled={busy}>תשמרו לי מקום<ArrowLeft size={16}/></button></form>}
// Bit has no public link that pre-fills the recipient or amount, so the button copies the creditor's
// phone (awaited, before leaving the page) and then opens Bit through its verified app link (/app/*).
const mobile=/Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
function BitLink({to,amount,notify}){const shekels=amount%100?(amount/100).toFixed(2):String(amount/100),href=`https://www.bitpay.co.il/app/pay-request/?phone=972${to.phone.slice(1)}&amount=${shekels}`;return <a className="bit-button" href={href} onClick={async e=>{e.preventDefault();let copied=false;try{await navigator.clipboard.writeText(to.phone);copied=true}catch{}notify(copied?`הטלפון של ${to.name} הועתק · להדביק בביט ולהזין ${shekels} ₪`:`הטלפון של ${to.name}: ${to.phone}`);if(mobile)location.href=href;else window.open(href,'_blank','noopener')}}>העברה בביט<ArrowLeft size={15}/></a>}
function RequestForm({state,actorId,kind,other,submit,busy}){const [target,setTarget]=useState(other||state.users.find(u=>u.id!==actorId)?.id||''),[direction,setDirection]=useState('owe'),[error,setError]=useState(''),[confirm,setConfirm]=useState(null);const b=balance(state,actorId,target);if(confirm)return <><div className="notice"><Info/><p>{state.users.find(u=>u.id===confirm.from)?.name} משלם ל{state.users.find(u=>u.id===confirm.to)?.name} {money(confirm.amount)}. הבקשה תמתין לאישור הצד השני.</p></div><button className="primary wide" disabled={busy} onClick={()=>submit(confirm)}>אישור ושליחת הבקשה</button><button className="text-button" onClick={()=>setConfirm(null)}>חזרה לעריכה</button></>;return <form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);setConfirm({type:'request',kind,from:(kind==='payment'?b>0:direction==='owe')?actorId:target,to:(kind==='payment'?b>0:direction==='owe')?target:actorId,amount:cents(f.get('amount')),reason:f.get('reason')})}catch(e){setError(e.message)}}}><Field label="עם מי סוגרים חשבון?"><select value={target} onChange={e=>setTarget(e.target.value)} required>{state.users.filter(u=>u.id!==actorId).map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></Field>{kind==='manual'?<Field label="מי חייב למי?"><select value={direction} onChange={e=>setDirection(e.target.value)}><option value="owe">אני חייב לשחקן</option><option value="receive">השחקן חייב לי</option></select></Field>:<div className="notice">היתרה הפתוחה: {money(Math.abs(b))}. ניתן לדווח גם על תשלום חלקי.</div>}<Field label="סכום (₪)"><input key={target} name="amount" inputMode="decimal" defaultValue={kind==='payment'?Math.abs(b)/100:''} required/></Field><Field label={kind==='manual'?'סיבת החוב':'הערה (אופציונלית)'}><input name="reason" placeholder={kind==='manual'?'למשל: הפיצה של הערב':'למשל: העברה בביט'} required={kind==='manual'} maxLength="300"/></Field>{error&&<p className="negative">{error}</p>}<button className="primary wide" disabled={busy||!target}>המשך לאישור</button></form>}
function CloseForm({session:s,user,submit,correction,busy}){const [values,set]=useState(Object.fromEntries(s.players.map(id=>[id,String((s.results.find(r=>r.userId===id)?.final??buyTotal(s,id))/100)]))),[distribute,setDistribute]=useState(false),[stage,setStage]=useState(0),[error,setError]=useState(''),[reason,setReason]=useState(''),[transfers,setTransfers]=useState([]),[snapshot,setSnapshot]=useState(null);let finals={},results=[],delta=0;try{finals=Object.fromEntries(Object.entries(values).map(([id,v])=>[id,cents(v,true)]));delta=s.players.reduce((n,id)=>n+buyTotal(s,id)-finals[id],0);results=calculate(s,finals,true)}catch{}const next=()=>{try{const r=calculate(s,finals,distribute);setTransfers(settle(r));setSnapshot({version:s.version,finals,distribute,results:r});setStage(1);setError('')}catch(e){setError(e.message)}};return <>{stage===0?<><p className="muted">כמה כסף נשאר לכל שחקן? נחשב את התוצאה ואת ההעברות.</p>{s.players.map(id=><div className="closing-row" key={id}><Avatar user={user(id)}/><div><strong>{user(id)?.name}</strong><small>נכנס עם {money(buyTotal(s,id))}</small></div><label><span className="sr-only">סכום סופי של {user(id)?.name}</span><input inputMode="decimal" value={values[id]} onChange={e=>set({...values,[id]:e.target.value})}/><span>₪</span></label></div>)}<div className={`notice ${delta?'warning':''}`}><Info size={18}/>{delta?`יש ${delta>0?'חוסר':'עודף'} של ${money(Math.abs(delta))}. יש לתקן את הסכומים או לאשר חלוקה שווה.`:'כל הכסף מאוזן. אפשר להתקדם לתוכנית ההעברות.'}</div>{delta!==0&&<><label className="checkbox"><input type="checkbox" checked={distribute} onChange={e=>setDistribute(e.target.checked)}/>חלוקה שווה של ההפרש, כולל שארית באגורות</label>{distribute&&results.map(r=><div className="adjustment" key={r.userId}>{user(r.userId)?.name}<Money value={r.adjustment} signed/></div>)}</>}{correction&&<Field label="סיבת התיקון (חובה)"><textarea value={reason} onChange={e=>setReason(e.target.value)}/></Field>}<button className="primary wide" onClick={next} disabled={correction&&!reason.trim()}>המשך לתוכנית ההעברות<ArrowLeft size={17}/></button></>:<><div className="notice"><ShieldCheck/><p>יש לאשר את התוכנית כדי לסגור את הערב וליצור את החובות. אפשר לערוך, להוסיף או לפצל העברות; היתרות חייבות להישאר מדויקות.</p></div>{snapshot.results.map(r=><div className="adjustment" key={r.userId}><strong>{user(r.userId)?.name}</strong><Money value={r.net} signed/></div>)}<div className="transfer-editor">{transfers.map((t,i)=><div key={i}><select aria-label={`משלם בהעברה ${i+1}`} value={t.from} onChange={e=>setTransfers(transfers.map((v,j)=>i===j?{...v,from:e.target.value}:v))}>{s.players.map(id=><option key={id} value={id}>{user(id)?.name}</option>)}</select><ArrowLeft size={16}/><select aria-label={`מקבל בהעברה ${i+1}`} value={t.to} onChange={e=>setTransfers(transfers.map((v,j)=>i===j?{...v,to:e.target.value}:v))}>{s.players.map(id=><option key={id} value={id}>{user(id)?.name}</option>)}</select><input aria-label={`סכום העברה ${i+1}`} inputMode="decimal" value={t.edit??String(t.amount/100)} onChange={e=>setTransfers(transfers.map((v,j)=>i===j?{...v,edit:e.target.value}:v))}/><button className="icon-button" aria-label="מחיקת העברה" onClick={()=>setTransfers(transfers.filter((_,j)=>j!==i))}><X size={16}/></button></div>)}</div><button className="text-button" onClick={()=>setTransfers([...transfers,{from:s.players[0],to:s.players[1],amount:100}])}><Plus size={16}/>הוספת העברה</button><div className="dialog-actions"><button className="primary" disabled={busy} onClick={()=>{try{const ts=transfers.map(({edit,...t})=>({...t,amount:edit===undefined?t.amount:cents(edit)}));validateTransfers(snapshot.results,ts);submit({type:correction?'correct':'close',sessionId:s.id,finals:snapshot.finals,distribute:snapshot.distribute,version:snapshot.version,transfers:ts,reason})}catch(e){setError(e.message)}}}>אישור סופי וסגירת הערב<CheckCheck size={17}/></button><button className="secondary" onClick={()=>setStage(0)}>חזרה לסכומים</button></div></>}{error&&<p className="negative" role="alert">{error}</p>}</>}

function StatsView({state,actorId,period,range,user}){const today=israelDay(new Date()),y=Number(today.slice(0,4)),m=Number(today.slice(5,7))-1;let from='',to='';if(period==='month')from=`${y}-${String(m+1).padStart(2,'0')}-01`;if(period==='last'){const d=new Date(y,m-1,1);from=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;to=new Date(y,m,0,12).toISOString().slice(0,10)}if(period==='year')from=`${y}-01-01`;if(period==='custom'){from=range.from;to=range.to}const s=statistics(state,actorId,from,to),leaders=state.users.map(u=>({u,s:statistics(state,u.id,from,to)})).sort((a,b)=>b.s.total-a.s.total),record=[...leaders].sort((a,b)=>b.s.best-a.s.best);const monthly=Object.values(s.sessions.reduce((obj,se)=>{const k=month(se.date);obj[k]??={key:k,net:0};obj[k].net+=se.results.find(r=>r.userId===actorId).net;return obj},{}));const [compare,setCompare]=useState('');const cs=compare?statistics(state,compare,from,to):null;return <><div className="metric-grid"><Metric label="רווח בתקופה" value={s.total} signed icon={TrendingUp} special/><Metric label="משחקים ששיחקתי" text={s.count} icon={Spade}/><Metric label="משחקים ברווח" text={`${s.winRate}%`} icon={ChartNoAxesCombined}/><Metric label="הערב הכי טוב" value={s.best} signed icon={Trophy}/></div><section className="panel"><div className="section-title"><h2>הרווח המצטבר שלי</h2><TrendingUp size={19}/></div><Chart results={s.results}/></section><div className="two-columns">{[[leaders,'הטבלה לא משקרת','דירוג רווח כולל','total'],[record,'שיא רווח בערב','הרווח הגבוה ביותר בישיבה אחת','best']].map(([list,title,sub,key])=><section className="panel" key={key}><div className="section-title"><div><h2>{title}</h2><p>{sub}</p></div><Trophy className="gold" size={21}/></div>{list.map(({u,s},i)=><div className="leader" key={u.id}><span className={`rank rank-${i}`}>{i+1}</span><Avatar user={u}/><div><strong>{u.name}</strong><small>{s.count} משחקים</small></div><Money value={s[key]} signed/></div>)}</section>)}</div><section className="panel"><h2>עוד קצת על המשחק שלך</h2><div className="detail-metrics">{[['משחקים ברווח',s.wins],['משחקים בהפסד',s.losses],['רווח ממוצע לערב',money(s.average,true)],['הפסד ממוצע בערב הפסדי',money(s.averageLoss,true)],['הערב הכי פחות מוצלח',money(s.worst,true)],['סך הכניסות',money(s.buyins)],['כניסה ממוצעת לערב',money(s.count?Math.round(s.buyins/s.count):0)],['כניסות נוספות',s.rebuys],['רצף משחקים ברווח',s.maxW],['רצף משחקים בהפסד',s.maxL]].map(([label,value])=><div key={label}><small>{label}</small><strong>{value}</strong></div>)}</div></section><div className="two-columns"><section className="panel"><h2>חודש אחרי חודש</h2>{monthly.map(v=><div className="activity" key={v.key}><CalendarDays size={18}/><strong>{v.key}</strong><Money value={v.net} signed/></div>)}</section><section className="panel"><h2>השוואה עם חבר</h2><Field label="בחירת שחקן"><select value={compare} onChange={e=>setCompare(e.target.value)}><option value="">בחרו חבר להשוואה</option>{state.users.filter(u=>u.id!==actorId).map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></Field>{cs&&<><div className="comparison-head"><span>מדד</span><strong>{user(actorId)?.name}</strong><strong>{user(compare)?.name}</strong></div>{[['רווח מצטבר',money(s.total,true),money(cs.total,true)],['ממוצע לערב',money(s.average,true),money(cs.average,true)],['משחקים ברווח',s.winRate+'%',cs.winRate+'%'],['סך כניסות',money(s.buyins),money(cs.buyins)]].map(row=><div className="comparison-head" key={row[0]}>{row.map((v,i)=><span key={i}>{v}</span>)}</div>)}</>}</section></div><section className="panel"><div className="section-title"><h2>רווח/הפסד לפי מיקום</h2><MapPin size={19}/></div>{s.places.length?s.places.map(p=><div className="activity" key={p.key}><span className="session-icon"><MapPin size={18}/></span><div><strong>{p.label}</strong><small>{p.count===1?"ערב אחד":`${p.count} משחקים`}</small></div><Money value={p.net} signed/></div>):<p className="muted">אין עדיין משחקים סגורים בתקופה הזו.</p>}</section></>}
function Login({onLogin,disabled}){const [busy,setBusy]=useState(false);return <form onSubmit={async e=>{e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget);try{await onLogin(f.get('phone'),f.get('password'))}finally{setBusy(false)}}}><Field label="מספר טלפון"><input name="phone" type="tel" inputMode="numeric" autoComplete="tel" placeholder="05X-XXXXXXX" dir="ltr" required/></Field><Field label="סיסמה"><input name="password" type="password" autoComplete="current-password" required/></Field><button className="primary wide" disabled={busy||disabled}>כניסה לשולחן<ArrowLeft size={18}/></button><p className="footnote">שכחת סיסמה? מנהל הקבוצה יכול לאפס אותה.</p></form>}
function PasswordForm({onSubmit,compact=false}){const [error,setError]=useState(''),[busy,setBusy]=useState(false);return <form onSubmit={async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),p=f.get('password');setError('');if(p.length<4)return setError('הסיסמה צריכה להכיל לפחות 4 תווים');if(p===DEFAULT_PASSWORD)return setError('יש לבחור סיסמה שונה מהסיסמה הראשונית');if(p!==f.get('confirm'))return setError('הסיסמאות אינן תואמות');setBusy(true);try{await onSubmit(p);form.reset()}finally{setBusy(false)}}}><Field label="סיסמה חדשה"><input name="password" type="password" autoComplete="new-password" minLength="4" required/></Field><Field label="אימות סיסמה"><input name="confirm" type="password" autoComplete="new-password" required/></Field>{error&&<p className="negative">{error}</p>}<button className={compact?'secondary':'primary wide'} disabled={busy}>{compact?'עדכון סיסמה':'שמירה וכניסה'}<KeyRound size={16}/></button></form>}
// Gallery photos are center-cropped and downscaled so they fit comfortably in the shared action log.
async function shrinkImage(file){const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('לא ניתן לקרוא את התמונה'));i.src=url});const size=256,side=Math.min(img.width,img.height),canvas=document.createElement('canvas');canvas.width=canvas.height=size;canvas.getContext('2d').drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,size,size);return canvas.toDataURL('image/jpeg',.82)}finally{URL.revokeObjectURL(url)}}
function ProfileForm({actor,busy,submit}){const [avatar,setAvatar]=useState(actor.avatar||''),[error,setError]=useState('');return <><div className="profile-preview"><Avatar user={{...actor,avatar}} size="large"/><div><h2>{actor.name}</h2><p>חבר מאז {date(actor.joined)}</p></div></div><form onSubmit={e=>{e.preventDefault();submit({type:'profile',name:new FormData(e.currentTarget).get('name'),avatar})}}><Field label="שם תצוגה"><input name="name" defaultValue={actor.name} minLength="2" maxLength="40" required/></Field><div className="photo-actions"><label className="secondary file-button"><Upload size={17}/>{avatar?'החלפת תמונה מהגלריה':'בחירת תמונה מהגלריה'}<input type="file" accept="image/*" hidden onChange={async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{setError('');setAvatar(await shrinkImage(file))}catch(err){setError(err.message)}}}/></label>{avatar&&<button type="button" className="text-button" onClick={()=>setAvatar('')}><X size={14}/>הסרת התמונה</button>}</div>{error&&<p className="negative">{error}</p>}<button className="primary" disabled={busy}>שמירת פרופיל</button></form></>}

